∀ {α : Type u} [inst : PseudoMetricSpace α] {β : Type u_3} {p : β → Prop} {f : β → ℝ},
  (∀ (i : β), p i → 0 < f i) →
    (∀ ⦃ε : ℝ⦄, 0 < ε → ∃ i, p i ∧ f i ≤ ε) → (uniformity α).HasBasis p fun i => {p | dist p.1 p.2 < f i}

∀ {α : Type u} [inst : PseudoMetricSpace α] {β : Type u_3} {p : β → Prop} {f : β → ℝ},
  (∀ (x : β), p x → 0 < f x) →
    (∀ (ε : ℝ), 0 < ε → ∃ x, p x ∧ f x ≤ ε) → (uniformity α).HasBasis p fun x => {p | dist p.1 p.2 ≤ f x}

∀ {α : Type u} {β : Type v} [inst : PseudoMetricSpace α] {s : Set α} [inst_1 : PseudoMetricSpace β] {f : α → β} {a : α}
  {b : β},
  Filter.Tendsto f (nhdsWithin a s) (nhds b) ↔ ∀ ε > 0, ∃ δ > 0, ∀ ⦃x : α⦄, x ∈ s → dist x a < δ → dist (f x) b < ε

∀ {α : Type u_3} (d : α → α → NNReal),
  ⨅ ε, ⨅ (_ : ε > 0), Filter.principal {p | ↑(d p.1 p.2) < ε} =
    ⨅ ε, ⨅ (_ : ε > 0), Filter.principal {p | ↑(d p.1 p.2) < ε}

∀ {α : Type u} [inst : PseudoMetricSpace α] {β : Type u_3} {p : β → Prop} {f : β → ℝ} {l : Filter β} [l.NeBot],
  (∀ (i : β), p i → 0 < f i) →
    (∀ᶠ (i : β) in l, p i) → Filter.Tendsto f l (nhds 0) → (uniformity α).HasBasis p fun i => {x | dist x.1 x.2 < f i}
